const items = $input.all();
return items.map((item, index) => {
  const enquiry = item.json;
  if (enquiry.dataSource !== 'synthetic') {
    throw new Error('This demo accepts synthetic data only. Do not connect real enquiries yet.');
  }
  const propertyName = typeof enquiry.propertyName === 'string' ? enquiry.propertyName.trim() : '';
  if (!propertyName) throw new Error('A fictional property name is required.');
  const photoCount = Number(enquiry.photoCount);
  if (!Number.isInteger(photoCount) || photoCount < 0 || photoCount > 50) {
    throw new Error('photoCount must be a whole number between 0 and 50.');
  }
  const hasListedPhotos = photoCount > 0;
  const disclaimer = 'SIMULATED DEMO — no AI model was called, no photographs were opened, and no property suitability was assessed.';
  const draftReading = [
    '# ' + propertyName + ' — simulated property reading',
    '',
    disclaimer,
    '',
    '## Supplied sample information',
    '- Fictional property: ' + propertyName,
    '- Number of photographs listed in the sample: ' + photoCount,
    '- Photographs actually analysed: 0',
    '',
    '## Example structure only',
    hasListedPhotos
      ? 'A future review could consider an arrival, a threshold and a distinctive property experience. These are planning categories, not claims about this property or its photographs.'
      : 'The sample lists no photographs. A real reading would need permission-cleared material before assessing a journey.',
    '',
    '## Questions for a future real review',
    '- Which photographs may be used, and for what purpose?',
    '- Which spaces genuinely connect? A photo count cannot establish a route.',
    '- What should the visitor do next: enquire, book or learn more?',
    '',
    '## Next owner action',
    'Review this sample output in n8n. Nothing has been saved to Studio or sent to a client.'
  ].join('\n');
  const draftReply = hasListedPhotos
    ? 'DEMO ONLY — Thanks for your enquiry. Before assessing a cinematic website, please confirm permission to review the photographs and tell us which spaces connect. We will identify what can be supported by the material and any missing views.'
    : 'DEMO ONLY — Thanks for your enquiry. Please share a small selection of permission-cleared photographs so we can begin a first reading.';
  return {
    json: {
      enquiryId: enquiry.enquiryId,
      propertyName,
      mode: 'simulated',
      aiUsed: false,
      apiCalls: 0,
      estimatedAiCostUsd: 0,
      imagesAnalysed: 0,
      taskStatus: 'Awaiting owner review',
      materialStatus: hasListedPhotos ? 'Photo count supplied; files not inspected' : 'No photographs listed',
      draftReading,
      draftReply,
      approvalRecorded: false,
      savedToStudio: false,
      sentToClient: false,
      nextAction: 'Read the draft output. Do not send this demo as a real property assessment.'
    },
    pairedItem: { item: index }
  };
});
